inkMethods.constructor:
constructor(system) {
    this.system = system; this.drops = []; this.pool = []; this.time = 0;
    this.worldHit = new Hit(); this.dropHit = new Hit();
    this.base = new THREE.Vector3(); this.point = new THREE.Vector3(); this.normal = new THREE.Vector3();
    this.heading = new THREE.Vector3(); this.matrix = new THREE.Matrix4(); this.rotation = new THREE.Quaternion(); this.scale = new THREE.Vector3();
    this.stats = { spawned: 0, landed: 0, headImpacts: 0, peakDrops: 0 };
    this.trace = null;
  }

inkMethods.clear:
clear() {
    this.pool.push(...this.drops); this.drops.length = 0; this.time = 0;
    Object.assign(this.stats, { spawned: 0, landed: 0, headImpacts: 0, peakDrops: 0 });
  }

inkMethods.emitAlong:
emitAlong(p, length, stop, previousAge, collision) {
    const plan = p.inkPlan, end = p.inkTravel + length * stop;
    while (p.inkSpawned < plan.count) {
      const at = plan.first + p.inkSpawned * plan.spacing;
      if (at > end + EPS || collision && at >= end - EPS) break;
      const fraction = length > EPS ? Math.max(0, (at - p.inkTravel) / length) : 0;
      this.point.copy(p.prev).lerp(p.pos, fraction);
      this.spawnDrop(p, this.point, p.inkSpawned, p.inkBirth + previousAge + fraction * INK_DT);
      p.inkSpawned++;
    }
  }

inkMethods.spawnDrop:
spawnDrop(head, at, index, birth) {
    const p = this.pool.pop() || { pos: new THREE.Vector3(), prev: new THREE.Vector3(), vel: new THREE.Vector3(), heading: new THREE.Vector3() };
    const profile = head.inkProfile, feet = index === 0 && head.inkPlan.feet;
    const seed = seededUnit(head.seed, 37 + index), h = Math.hypot(head.vel.x, head.vel.z);
    const fx = h > EPS ? head.vel.x / h : 0, fz = h > EPS ? head.vel.z / h : 1;
    const lateral = (seededUnit(seed, 1) * 2 - 1) * INK_MODEL.dropRandomX * INK_HZ * INK_LENGTH_SCALE;
    const forward = (INK_MODEL.dropRandomZMin + seededUnit(seed, 2) * (INK_MODEL.dropRandomZMax - INK_MODEL.dropRandomZMin)) * INK_HZ * INK_LENGTH_SCALE;
    p.vel.set(fx * forward + fz * lateral,
      (seededUnit(seed, 3) * 2 - 1) * INK_MODEL.dropRandomY * INK_HZ * INK_LENGTH_SCALE,
      fz * forward - fx * lateral);
    p.pos.copy(at); p.prev.copy(at); p.heading.set(fx, 0, fz);
    p.inkKey = head.inkKey; p.s3Weapon = head.s3Weapon;
    p.owner = head.owner; p.team = head.team; p.ghost = head.ghost; p.profile = profile;
    p.feet = feet; p.seed = seed; p.birth = birth; p.age = 0; p.frame = 0; p.startY = at.y;
    this.drops.push(p); this.stats.spawned++; this.stats.peakDrops = Math.max(this.stats.peakDrops, this.drops.length);
    this.trace?.({ event: 'drop-born', weapon: head.inkKey, sequence: head.inkSequence, index, feet, time: birth, pos: at.toArray(), ghost: !!p.ghost });
  }

inkMethods.updateDrops:
updateDrops() {
    for (let i = this.drops.length - 1; i >= 0; i--) {
      const p = this.drops[i], targetAge = this.time - p.birth;
      let dead = false;
      while ((p.frame + 1) * INK_DT <= targetAge + EPS) {
        p.prev.copy(p.pos); p.frame++; p.age = p.frame * INK_DT;
        p.vel.multiplyScalar(1 - INK_MODEL.dropDrag);
        p.vel.y -= INK_MODEL.dropGravity * INK_HZ * INK_LENGTH_SCALE;
        p.pos.addScaledVector(p.vel, INK_DT);
        const hit = this.world(p.prev, p.pos, INK_MODEL.dropFieldRadius, this.dropHit);
        if (hit.hit) {
          if (!p.ghost) {
            const shape = splashShape(p.profile, p.feet, Math.max(0, p.startY - hit.point.y));
            this.paint(p, hit, splashPaintFootprint(shape), p.heading, p.feet ? 'trail' : 'drop');
            this.stats.landed++;
            emit('weapon:impact', { pos: hit.point.clone(), normal: hit.normal.clone(), team: p.team, kind: 'drop', radius: shape.radius });
            this.trace?.({ event: 'drop-landed', time: p.birth + p.age, feet: p.feet, pos: hit.point.toArray(), face: hit.face });
          }
          dead = true; break;
        }
        if (p.age + EPS >= INK_MODEL.dropLife || p.pos.y < PLAYER.waterY - 1.8) { dead = true; break; }
      }
      if (dead) { this.drops[i] = this.drops[this.drops.length - 1]; this.drops.pop(); this.pool.push(p); }
    }
  }

inkMethods.draw:
draw(blobs, shapes, index, capacity) {
    for (const p of this.drops) {
      if (index >= capacity) break; // visual cap never limits gameplay or paint
      const speed = p.vel.length(); this.normal.copy(p.vel).multiplyScalar(1 / Math.max(EPS, speed));
      if (speed < EPS) this.normal.copy(Z);
      this.rotation.setFromUnitVectors(Z, this.normal);
      const growth = Math.min(1, 0.7 + p.age * 20);
      this.scale.setScalar(INK_MODEL.dropDrawRadius * (p.feet ? 1.15 : 1) * growth);
      this.matrix.compose(p.pos, this.rotation, this.scale);
      blobs.setMatrixAt(index, this.matrix); blobs.setColorAt(index, p.owner.color);
      const offset = index * 4; shapes[offset] = 1 + Math.min(0.8, speed * 0.025);
      shapes[offset + 1] = 0.035; shapes[offset + 2] = p.seed * 40 + p.age * 22; shapes[offset + 3] = 0.2;
      index++;
    }
    return index;
  }

spawnSplashDrop:
function spawnSplashDrop(game, { owner, team, seed, salt = 0, from, direction = null, radius, spec,
  depth = true, kind = 'drop', initialDownSpeed = 0, catchUpSeconds = 0, footprint = null }) {
  const queue = dropQueue(game);
  if (!queue || !owner || owner.remote || !(radius > 0) || !spec || !from) return null;
  const V = from.constructor;
  const dirX = direction ? direction.x : 0, dirZ = direction ? direction.z : 0, len = Math.hypot(dirX, dirZ);
  const fx = len > EPS ? dirX / len : 0, fz = len > EPS ? dirZ / len : 0;
  const random = spec.randomVelocity, unit = k => seededSplashUnit(seed, (salt * 8 + k) >>> 0);
  // Sourced per-axis random spawn velocity (zero for every 11.3.0 Blaster but
  // Precision): X/Y symmetric, Z in [ZMin, ZMax] along the shot direction.
  const vx = random ? (unit(1) * 2 - 1) * random.x : 0, vy = random ? (unit(2) * 2 - 1) * random.y : 0;
  const vz = random ? random.zMin + unit(3) * (random.zMax - random.zMin) : 0;
  const pool=game.projectiles._s3SplashDropPool||=([]);
  let drop=pool.pop();
  if(!drop||drop.pos.constructor!==V)drop={pos:new V(),vel:new V(),next:new V(),hit:hitRecord(from)};
  const collision=drop.hit;
  collision.hit=false;collision.dist=0;collision.block=collision.face=-1;collision.u=collision.v=0;
  collision.point.set(0,0,0);collision.normal.set(0,0,0);
  Object.assign(drop,{
    owner, team, seed: unit(0), radius, spec, depth, kind, footprint,
    dirX: fx, dirZ: fz, spawnY: from.y, releaseX: from.x, releaseZ: from.z, frames: 0,
    carry: Number.isFinite(catchUpSeconds) && catchUpSeconds > 0 ? catchUpSeconds * STEP_FRAMES_PER_SECOND : 0,
    landing:null,landingDepth:undefined,drawRadius:undefined,sourceActor:undefined,_s3SplashDropPooled:false,
  });
  drop.pos.set(from.x,from.y,from.z);
  drop.vel.set(fx*vz-fz*vx,vy-Math.max(0,initialDownSpeed),fz*vz+fx*vx);
  drop.next.set(0,0,0);
  queue.push(drop);
  return drop;
}

paintDistanceFlight:
function paintDistanceFlight(game, projectile, state, end = projectile?.pos) {
  if (!state || (projectile.s3SpecialWeapon && !(projectile.s3AllSpecial === 'crabTank' && state === projectile.s3CrabFlightPaint)) || projectile.ghost ||
      projectile.owner?.remote || !game?.paint || !game?.physics ||
      !end || ![end.x, end.y, end.z].every(Number.isFinite)) return 0;
  const distance = state.last.distanceTo(end), limit = state.distance + distance, spec = state.spec;
  if (!(distance > EPS)) return 0;
  let released = 0;
  while (state.index < spec.count) {
    const at = spec.first + state.index * spec.spacing;
    if (at > limit + EPS) break;
    const index = state.index++;
    state.sample.copy(state.last).lerp(end, Math.max(0, Math.min(1, (at - state.distance) / distance)));
    state.direction.set(end.x - state.last.x, 0, end.z - state.last.z);
    const radius = index === 0 ? spec.nearestWidth : spec.width, kind = index === 0 && spec.nearestIsFeet ? 'trail' : 'drop';
    released++;
    // SplashWallHitParam: a splash released with a paintable wall inside its
    // sourced reach sticks to that wall instead of falling to the floor.
    if (typeof state.wallSplash === 'function' && state.wallSplash(state.sample, index)) continue;
    const drop = spawnSplashDrop(game, { owner: projectile.owner, team: projectile.team, seed: projectile.seed,
      salt: index, from: state.sample, direction: state.direction, radius, spec, depth: true, kind,
      footprint: mainInkFootprint(projectile.s3Weapon || projectile.catalog?.r) });
    if (!drop) paintImmediate(game, projectile, state, index, radius);
  }
  state.distance = limit; state.last.copy(end);
  return released;
}

paintImmediate:
function paintImmediate(game, projectile, state, index, radius) {
  const drop = { owner: projectile.owner, team: projectile.team, seed: seededSplashUnit(projectile.seed, index * 8),
    footprint: mainInkFootprint(projectile.s3Weapon || projectile.catalog?.r),
    radius, spec: state.spec, depth: true, kind: 'drop', dirX: 0, dirZ: 0, spawnY: state.sample.y, frames: 0,
    pos: state.sample.clone(), next: state.sample.clone(), hit: null };
  const len = Math.hypot(state.direction.x, state.direction.z);
  if (len > EPS) { drop.dirX = state.direction.x / len; drop.dirZ = state.direction.z / len; }
  drop.next.y -= 1000;
  const hit = game.physics.segment(drop.pos, drop.next, hitRecord(drop.pos), true);
  drop.frames = hit?.hit ? Math.ceil(Math.sqrt(2 * Math.max(0, drop.spawnY - hit.point.y) / state.spec.gravity) * STEP_FRAMES_PER_SECOND) : 0;
  if (hit?.hit) landSplashDrop(game, drop, hit);
}

